package com.example.globalshop.network;

import com.example.globalshop.shop.Listing;
import java.util.UUID;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.world.item.ItemStack;

/**
 * One listing as it travels to a client.
 *
 * <p>Deliberately a flat, immutable snapshot rather than the server's
 * {@link Listing}: the client cannot reach server state through it, and it carries
 * only what the screen draws. Everything here is generated by the server; nothing
 * the client sends ever travels this way.
 *
 * @param display        a single unit of the item, for the icon and the name
 * @param ownedByViewer  lets the screen offer "edit / unlist" instead of "buy"
 * @param soldOut        shown in the seller's own view so they can restock
 * @param sellerVip      the seller's rank, so a buyer can see who they are dealing with
 * @param expired        timed out: shown to the seller, and unbuyable
 */
public record ListingView(UUID id,
                          UUID sellerId,
                          String sellerName,
                          ItemStack display,
                          long unitPrice,
                          int stock,
                          int minPerBuy,
                          int maxPerBuy,
                          long listedAt,
                          boolean ownedByViewer,
                          boolean soldOut,
                          boolean sellerVip,
                          boolean expired) {

    private static final int MAX_NAME_LENGTH = 64;

    public static ListingView of(Listing listing, UUID viewerId, boolean sellerVip) {
        return new ListingView(
                listing.id(),
                listing.sellerId(),
                listing.sellerName(),
                listing.template().copy(),
                listing.unitPrice(),
                listing.stock(),
                listing.minPerBuy(),
                listing.maxPerBuy(),
                listing.listedAt(),
                listing.isSeller(viewerId),
                listing.isSoldOut(),
                sellerVip,
                listing.isExpired());
    }

    public void encode(FriendlyByteBuf buf) {
        buf.writeUUID(id);
        buf.writeUUID(sellerId);
        buf.writeUtf(sellerName, MAX_NAME_LENGTH);
        buf.writeItem(display);
        buf.writeLong(unitPrice);
        buf.writeInt(stock);
        buf.writeInt(minPerBuy);
        buf.writeInt(maxPerBuy);
        buf.writeLong(listedAt);
        buf.writeBoolean(ownedByViewer);
        buf.writeBoolean(soldOut);
        buf.writeBoolean(sellerVip);
        buf.writeBoolean(expired);
    }

    public static ListingView decode(FriendlyByteBuf buf) {
        return new ListingView(
                buf.readUUID(),
                buf.readUUID(),
                buf.readUtf(MAX_NAME_LENGTH),
                buf.readItem(),
                buf.readLong(),
                buf.readInt(),
                buf.readInt(),
                buf.readInt(),
                buf.readLong(),
                buf.readBoolean(),
                buf.readBoolean(),
                buf.readBoolean(),
                buf.readBoolean());
    }

    /** Highest quantity a buyer could pick right now. */
    public int effectiveMaxPerBuy() {
        return Math.max(0, Math.min(maxPerBuy, stock));
    }
}
